WITH ref AS (SELECT DISTINCT d.entity_kind AS ok, d.entity_name AS oi, lower(replace(x[1], '.md', '')) AS док, x[2] AS ном FROM project_documents d CROSS JOIN LATERAL regexp_matches(d.content, '`([A-Za-z0-9_.-]+[.]md)`[^\n`§]{0,40}§([0-9]+(?:bis)?(?:[.][0-9]+)?)', 'g') AS x WHERE d.project_id = $1), цель AS (SELECT DISTINCT ON (r.ok, r.oi, r.док, r.ном) r.*, t.entity_kind AS вид, t.entity_name AS имя FROM ref r JOIN project_documents t ON t.project_id = $1 AND (lower(t.entity_name) = r.док OR (t.entity_name = '' AND lower(t.entity_kind) = r.док) OR lower(t.entity_name) LIKE '%/' || r.док) ORDER BY r.ok, r.oi, r.док, r.ном, (lower(t.entity_name) = r.док) DESC, t.entity_kind) SELECT ц.ok || ' ' || ц.oi || '  —  ' || ц.док || '.md §' || ц.ном || ': такого раздела нет' AS detail FROM цель ц WHERE EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = ц.вид AND s.entity_name = ц.имя AND s.title ~ '^[0-9]') AND NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = ц.вид AND s.entity_name = ц.имя AND split_part(s.title, '.', 1) = split_part(ц.ном, '.', 1)) ORDER BY 1
